    Bug 1980110 - Port bug 1971526: Move styling of toolbar separators to toolkit. r=freaktechnik


    Port of https://hg-edge.mozilla.org/mozilla-central/rev/c29285fdf3804c8a455d1f34b8a8fa6877328d47

    Differential Revision: https://phabricator.services.mozilla.com/D259224

diff --git a/mail/themes/shared/mail/customizeToolbar.css b/mail/themes/shared/mail/customizeToolbar.css
index a123c5c8309..e8f0967d738 100644
--- a/mail/themes/shared/mail/customizeToolbar.css
+++ b/mail/themes/shared/mail/customizeToolbar.css
@@ -74,6 +74,7 @@ toolbarpaletteitem {

     & toolbarseparator {
       background-color: currentColor;
+      padding: 0;
     }
   }

diff --git a/mail/themes/shared/mail/messenger.css b/mail/themes/shared/mail/messenger.css
index 63436cc4e28..e3b67a8a41f 100644
--- a/mail/themes/shared/mail/messenger.css
+++ b/mail/themes/shared/mail/messenger.css
@@ -772,6 +772,11 @@ html|ul.addon-installed-list {
                       var(--toolbarseparator-color) calc(100% - 4px),
                       transparent calc(100% - 4px));
     margin-inline: 1px;
+    padding: 0;
+
+    &:before {
+      display: none;
+    }
   }
 }

diff --git a/mail/themes/shared/mail/panelUI.css b/mail/themes/shared/mail/panelUI.css
index d1045bffd80..f60a8d24ef5 100644
--- a/mail/themes/shared/mail/panelUI.css
+++ b/mail/themes/shared/mail/panelUI.css
@@ -501,16 +501,16 @@ menuitem.panel-subview-footer:not([disabled])[_moz-menuactive]:active,
 .cui-widget-panel toolbarseparator {
   appearance: none;
   min-height: 0;
-  border-top: 1px solid var(--panel-separator-color);
-  border-bottom: none;
   margin: var(--panel-separator-margin);
   padding: 0;
+
+  &:before {
+    color: var(--panel-separator-color);
+  }
 }

 .PanelUI-subView toolbarseparator[orient="vertical"] {
   height: 24px;
-  border-inline-start: 1px solid var(--panel-separator-color);
-  border-top: none;
   margin: 0;
   margin-inline: 6px 7px;
 }
